function render() {
  var filtered = getFilteredTodos();
  var activeCount = todos.filter(function (t) { return !t.completed; }).length;
  var completedCount = todos.length - activeCount;

  // Show/hide main and footer
  var hasTodos = todos.length > 0;
  mainSection.style.display = hasTodos ? 'block' : 'none';
  footer.style.display = hasTodos ? 'block' : 'none';

  // In-place list reconciliation by data-id
  // Build a map of existing <li> elements keyed by data-id
  var existing = {};
  var i, li, todo, toggle, labelEl, editInput;
  for (i = 0; i < todoList.children.length; i++) {
    li = todoList.children[i];
    if (li.dataset.id) existing[li.dataset.id] = li;
  }

  // Track which todo ids should remain
  var remainingIds = {};
  for (i = 0; i < filtered.length; i++) {
    remainingIds[filtered[i].id] = true;
  }

  // Remove <li> elements whose todo is no longer in the filtered set
  for (var id in existing) {
    if (!remainingIds[id]) {
      todoList.removeChild(existing[id]);
      delete existing[id];
    }
  }

  // Rebuild the list in filtered order, reusing or creating <li> elements
  var fragment = document.createDocumentFragment();
  for (i = 0; i < filtered.length; i++) {
    todo = filtered[i];
    li = existing[todo.id];

    if (li) {
      // Update existing element in place
      var wasEditing = li.classList.contains('editing');
      li.className = todo.completed ? 'completed' : '';
      if (wasEditing) li.classList.add('editing');

      toggle = li.querySelector('.toggle');
      toggle.checked = todo.completed;

      labelEl = li.querySelector('label');
      labelEl.textContent = todo.title;

      editInput = li.querySelector('.edit');
      editInput.value = todo.title;
    } else {
      // Create new element for a todo that just appeared
      li = document.createElement('li');
      li.dataset.id = todo.id;
      if (todo.completed) li.className = 'completed';

      li.innerHTML =
        '<div class="view">' +
          '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>' +
          '<label>' + escapeHtml(todo.title) + '</label>' +
          '<button class="destroy"></button>' +
        '</div>' +
        '<input class="edit" value="' + escapeHtml(todo.title) + '">';

      // Event listeners capture todo via IIFE to preserve id per iteration
      (function (t) {
        li.querySelector('.toggle').addEventListener('change', function () {
          toggleTodo(t.id);
        });

        li.querySelector('.destroy').addEventListener('click', function () {
          removeTodo(t.id);
        });

        li.querySelector('label').addEventListener('dblclick', function () {
          var editEl = li.querySelector('.edit');
          li.classList.add('editing');
          editEl.focus();
          editEl.value = t.title;
        });

        var editInput = li.querySelector('.edit');
        editInput.addEventListener('keydown', function (e) {
          if (e.keyCode === ENTER_KEY) {
            e.preventDefault();
            updateTodo(t.id, editInput.value);
          }
          if (e.keyCode === ESCAPE_KEY) {
            editInput.value = t.title;
            li.classList.remove('editing');
          }
        });
        editInput.addEventListener('blur', function () {
          if (li.classList.contains('editing')) {
            updateTodo(t.id, editInput.value);
          }
        });
      })(todo);
    }

    fragment.appendChild(li);
  }

  // Replace list children in one operation (existing nodes moved to fragment and back)
  todoList.innerHTML = '';
  todoList.appendChild(fragment);

  // Update toggle-all checkbox
  toggleAllCheckbox.checked = completedCount === todos.length && todos.length > 0;

  // Update counter
  var itemWord = activeCount === 1 ? 'item' : 'items';
  todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' + itemWord + ' left';

  // Show/hide clear completed
  clearCompletedBtn.style.display = completedCount > 0 ? 'block' : 'none';

  // Update filter link classes
  Array.prototype.forEach.call(filterLinks, function (link) {
    var href = link.getAttribute('href');
    var filter = 'all';
    if (href === '#/active') filter = 'active';
    else if (href === '#/completed') filter = 'completed';
    if (filter === currentFilter) {
      link.className = 'selected';
    } else {
      link.className = '';
    }
  });
}

